schema:
CREATE TABLE PLAYER_ATTRIBUTES (
    ID INT,
    PLAYER_FIFA_API_ID INT,
    PLAYER_API_ID INT,
    OVERALL_RATING INT,
    FOREIGN KEY (player_fifa_api_id) REFERENCES Player(player_fifa_api_id),
    FOREIGN KEY (player_api_id) REFERENCES Player(player_api_id)
);

CREATE TABLE PLAYER (
    ID INT,
    PLAYER_API_ID INT,
    PLAYER_FIFA_API_ID INT
);

counterexample:
-- No INSERT statements are needed as the queries are identical and will always produce the same output.
-- Any valid data inserted will yield identical results for both Q1 and Q2.
-- Example of valid data (though not a counterexample):
